72	// ValidateInlinePromptSize rejects prompts that are too large to safely pass as
73	// a single CLI argument on providers that do not support stdin prompt input.
74	func ValidateInlinePromptSize(displayName, prompt string) error {
75		if len(prompt) <= MaxInlinePromptBytes {
76			return nil
77		}
78		return fmt.Errorf(
79			"%s prompt too large for CLI argument transport (%d bytes > %d bytes); choose a summary provider that accepts stdin for large transcripts",
80			displayName,
81			len(prompt),
82			MaxInlinePromptBytes,
83		)
84	}
